# Third-party code, word for word, for the tests of version 1.56 (issue 49). Each string was cut out of the raw source
# with an ast script, so what the tests run is what those programs run:
# - NVDA 2026.2 (tag release-2026.2, commit f62c980589d1ac30babf68ad48177e9ad29a2e84):
#   source/baseObject.py (blob 264c5a1166ad50b23e1bfc2767650b03e418c5df): Getter, CachingGetter, AutoPropertyType and
#   AutoPropertyObject, which make a class's _get_x and _set_x into the property x once, when the class is made;
#   source/synthSettingsRing.py (blob 770982bc94d4b3654e7e176c7af9e48ef3f9c631): SynthSetting, StringSynthSetting and
#   BooleanSynthSetting, the settings ring.
# - Eloquence64RS 19.1.4-RS (Nick6489/Eloquence64RS, tag v19.1.4-RS, commit 2e52c84b69fe88b239c8cabb76af3b2007a1b757),
#   addon/synthDrivers/eloquence.py (blob 6d88fb9246192c8193aab122cdeff17563df486c): the functions that keep a copy of the
#   voice's settings for each set of turned-on profiles, and apply it when NVDA switches to the set (ELOQUENCE_PROFILES),
#   and the methods of its SynthDriver that load and save settings and set the pitch and volume (ELOQUENCE_DRIVER_METHODS,
#   to go inside a class body, with the indentation they have there).

NVDA_AUTO_PROPERTY = 'class Getter(object):\n\tdef __init__(self, fget, abstract=False):\n\t\tself.fget = fget\n\t\tif abstract:\n\t\t\tself._abstract = self.__isabstractmethod__ = abstract\n\n\tdef __get__(\n\t\tself,\n\t\tinstance: Union[Any, None, "AutoPropertyObject"],\n\t\towner,\n\t) -> Union[GetterReturnT, "Getter"]:\n\t\tif isinstance(self.fget, classmethod):\n\t\t\treturn self.fget.__get__(instance, owner)()\n\t\telif instance is None:\n\t\t\treturn self\n\t\treturn self.fget(instance)\n\n\tdef setter(self, func):\n\t\treturn (abstractproperty if self._abstract else property)(fget=self.fget, fset=func)\n\n\tdef deleter(self, func):\n\t\treturn (abstractproperty if self._abstract else property)(fget=self.fget, fdel=func)\n\n\nclass CachingGetter(Getter):\n\tdef __get__(\n\t\tself,\n\t\tinstance: Union[Any, None, "AutoPropertyObject"],\n\t\towner,\n\t) -> Union[GetterReturnT, "CachingGetter"]:\n\t\tif isinstance(self.fget, classmethod):\n\t\t\tlog.warning("Class properties do not support caching")\n\t\t\treturn self.fget.__get__(instance, owner)()\n\t\telif instance is None:\n\t\t\treturn self\n\t\treturn instance._getPropertyViaCache(self.fget)\n\n\nclass AutoPropertyType(ABCMeta):\n\tdef __init__(self, name: str, bases: tuple[type, ...], namespace: dict[str, Any], /, **kwargs: Any):\n\t\tsuper().__init__(name, bases, namespace, **kwargs)\n\n\t\tcacheByDefault = False\n\t\ttry:\n\t\t\tcacheByDefault = namespace["cachePropertiesByDefault"]\n\t\texcept KeyError:\n\t\t\tcacheByDefault = any(getattr(base, "cachePropertiesByDefault", False) for base in bases)\n\n\t\t# Create a set containing properties that are marked as abstract.\n\t\tnewAbstractProps = set()\n\t\t# Create a set containing properties that were, but are no longer abstract.\n\t\toldAbstractProps = set()\n\t\t# given _get_myVal, _set_myVal, and _del_myVal: "myVal" would be output 3 times\n\t\t# use a set comprehension to ensure unique values, "myVal" only needs to occur once.\n\t\tprops = {x[5:] for x in namespace.keys() if x[0:5] in ("_get_", "_set_", "_del_")}\n\t\tfor x in props:\n\t\t\tg = namespace.get("_get_%s" % x, None)\n\t\t\ts = namespace.get("_set_%s" % x, None)\n\t\t\td = namespace.get("_del_%s" % x, None)\n\t\t\tif x in namespace:\n\t\t\t\tmethodsString = ",".join(str(i) for i in (g, s, d) if i)\n\t\t\t\traise TypeError(\n\t\t\t\t\t"%s is already a class attribute, cannot create descriptor with methods %s"\n\t\t\t\t\t% (x, methodsString),\n\t\t\t\t)\n\t\t\tif not g:\n\t\t\t\t# There\'s a setter or deleter, but no getter.\n\t\t\t\t# This means it could be in one of the base classes.\n\t\t\t\tfor base in bases:\n\t\t\t\t\tg = getattr(base, "_get_%s" % x, None)\n\t\t\t\t\tif g:\n\t\t\t\t\t\tbreak\n\n\t\t\tcache = namespace.get("_cache_%s" % x, None)\n\t\t\tif cache is None:\n\t\t\t\t# The cache setting hasn\'t been specified in this class, but it could be in one of the bases.\n\t\t\t\tfor base in bases:\n\t\t\t\t\tcache = getattr(base, "_cache_%s" % x, None)\n\t\t\t\t\tif cache is not None:\n\t\t\t\t\t\tbreak\n\t\t\t\telse:\n\t\t\t\t\tcache = cacheByDefault if not isinstance(g, classmethod) else False\n\n\t\t\tabstract = namespace.get("_abstract_%s" % x, False)\n\t\t\tif g and not (s or d):\n\t\t\t\tattr = (CachingGetter if cache else Getter)(g, abstract)\n\t\t\telse:\n\t\t\t\tattr = (abstractproperty if abstract else property)(fget=g, fset=s, fdel=d)\n\t\t\tif abstract:\n\t\t\t\tnewAbstractProps.add(x)\n\t\t\telif x in self.__abstractmethods__:\n\t\t\t\toldAbstractProps.add(x)\n\t\t\tsetattr(self, x, attr)\n\n\t\tif newAbstractProps or oldAbstractProps:\n\t\t\t# The __abstractmethods__ set is frozen, therefore we ought to override it.\n\t\t\tself.__abstractmethods__ = (self.__abstractmethods__ | newAbstractProps) - oldAbstractProps\n\n\nclass AutoPropertyObject(garbageHandler.TrackedObject, metaclass=AutoPropertyType):\n\t"""A class that dynamically supports properties, by looking up _get_*, _set_*, and _del_* methods at runtime.\n\t_get_x will make property x with a getter (you can get its value).\n\t_set_x will make a property x with a setter (you can set its value).\n\t_del_x will make a property x with a deleter that is executed when deleting its value.\n\tIf there is a _get_x but no _set_x then setting x will override the property completely.\n\tProperties can also be cached for the duration of one core pump cycle.\n\tThis is useful if the same property is likely to be fetched multiple times in one cycle.\n\tFor example, several NVDAObject properties are fetched by both braille and speech.\n\tSetting _cache_x to C{True} specifies that x should be cached.\n\tSetting it to C{False} specifies that it should not be cached.\n\tIf _cache_x is not set, L{cachePropertiesByDefault} is used.\n\tProperties can also be made abstract.\n\tSetting _abstract_x to C{True} specifies that x should be abstract.\n\tSetting it to C{False} specifies that it should not be abstract.\n\t"""\n\n\t#: Tracks the instances of this class; used by L{invalidateCaches}.\n\t#: @type: weakref.WeakKeyDictionary\n\t__instances = weakref.WeakKeyDictionary()\n\t#: Specifies whether properties are cached by default;\n\t#: can be overridden for individual properties by setting _cache_propertyName.\n\t#: @type: bool\n\tcachePropertiesByDefault = False\n\n\t_propertyCache: Set[GetterMethodT]\n\n\tdef __new__(cls, *args, **kwargs):\n\t\tself = super(AutoPropertyObject, cls).__new__(cls)\n\t\t#: Maps properties to cached values.\n\t\t#: @type: dict\n\t\tself._propertyCache = {}\n\t\tself.__instances[self] = None\n\t\treturn self\n\n\tdef _getPropertyViaCache(self, getterMethod: Optional[GetterMethodT] = None) -> GetterReturnT:\n\t\tif not getterMethod:\n\t\t\traise ValueError("getterMethod is None")\n\t\tmissing = False\n\t\ttry:\n\t\t\tval = self._propertyCache[getterMethod]\n\t\texcept KeyError:\n\t\t\tmissing = True\n\t\tif missing:\n\t\t\tval = getterMethod(self)\n\t\t\tself._propertyCache[getterMethod] = val\n\t\treturn val\n\n\tdef invalidateCache(self):\n\t\tself._propertyCache.clear()\n\n\t@classmethod\n\tdef invalidateCaches(cls):\n\t\t"""Invalidate the caches for all current instances."""\n\t\t# We use a list here, as invalidating the cache on an object may cause instances to disappear,\n\t\t# which would in turn cause an exception due to the dictionary changing size during iteration.\n\t\tfor instance in list(cls.__instances):\n\t\t\tinstance.invalidateCache()\n'

NVDA_SYNTH_SETTINGS = 'class SynthSetting(baseObject.AutoPropertyObject):\n\t"""a numeric synth setting. Has functions to set, get, increase and decrease its value"""\n\n\tdef __init__(self, synth, setting, min=0, max=100):\n\t\tself.synth = synth\n\t\tself.setting = setting\n\t\tself.min = setting.minVal if isinstance(setting, NumericDriverSetting) else min\n\t\tself.max = setting.maxVal if isinstance(setting, NumericDriverSetting) else max\n\t\tself.step = setting.normalStep if isinstance(setting, NumericDriverSetting) else 1\n\t\tself.largeStep = self.setting.largeStep if isinstance(setting, NumericDriverSetting) else 10\n\n\tdef first(self) -> str:\n\t\t"""Sets the value of the current synth setting to the first value."""\n\t\tval = self.min\n\t\tself.value = val\n\t\treturn self._getReportValue(val)\n\n\tdef last(self) -> str:\n\t\t"""Sets the value of the current synth setting to the last value."""\n\t\tval = self.max\n\t\tself.value = val\n\t\treturn self._getReportValue(val)\n\n\tdef increase(self):\n\t\tval = min(self.max, self.value + self.step)\n\t\tself.value = val\n\t\treturn self._getReportValue(val)\n\n\tdef increaseLarge(self) -> str:\n\t\t"""Increases the value of the current synth setting by a larger step."""\n\t\tval = min(self.max, self.value + self.largeStep * 2)\n\t\tself.value = val\n\t\treturn self._getReportValue(val)\n\n\tdef decrease(self):\n\t\tval = max(self.min, self.value - self.step)\n\t\tself.value = val\n\t\treturn self._getReportValue(val)\n\n\tdef decreaseLarge(self) -> str:\n\t\t"""Decreases the value of the current synth setting by a larger step."""\n\t\tval = max(self.min, self.value - self.largeStep * 2)\n\t\tself.value = val\n\t\treturn self._getReportValue(val)\n\n\tdef _get_value(self):\n\t\treturn getattr(self.synth, self.setting.id)\n\n\tdef _set_value(self, value):\n\t\tsetattr(self.synth, self.setting.id, value)\n\t\tconfig.conf["speech"][self.synth.name][self.setting.id] = value\n\n\tdef _getReportValue(self, val):\n\t\treturn str(val)\n\n\tdef _get_reportValue(self):\n\t\treturn self._getReportValue(self.value)\n\n\nclass StringSynthSetting(SynthSetting):\n\tdef _get__values(self):\n\t\tself._values = list(getattr(self.synth, f"available{self.setting.id.capitalize()}s").values())\n\t\treturn self._values\n\n\tdef _get_max(self):\n\t\treturn len(self._values) - 1\n\n\tdef _set_max(self, value):\n\t\t# Max is set by L{SynthSetting} but should always be a calculated property.\n\t\tpass\n\n\tdef _get_value(self):\n\t\tcurID = getattr(self.synth, self.setting.id)\n\t\tfor e, v in enumerate(self._values):\n\t\t\tif curID == v.id:\n\t\t\t\treturn e\n\n\tdef _set_value(self, value):\n\t\t"""Overridden to use code that supports updating speech dicts when changing voice"""\n\t\tid = self._values[value].id\n\t\tif self.setting.id == "voice":\n\t\t\tsynthDriverHandler.changeVoice(self.synth, id)\n\t\t\t# Voice parameters may change when the voice changes, so update the config.\n\t\t\tself.synth.saveSettings()\n\t\telse:\n\t\t\tsuper(StringSynthSetting, self)._set_value(id)\n\n\tdef _getReportValue(self, val):\n\t\treturn self._values[val].displayName\n\n\nclass BooleanSynthSetting(SynthSetting):\n\tdef __init__(self, synth, setting):\n\t\tsuper(BooleanSynthSetting, self).__init__(synth, setting, 0, 1)\n\n\tdef _get_value(self):\n\t\treturn int(super(BooleanSynthSetting, self).value)\n\n\tdef _set_value(self, val):\n\t\tsuper(BooleanSynthSetting, self)._set_value(bool(val))\n\n\tdef _getReportValue(self, val):\n\t\treturn _("on") if val else _("off")\n'

ELOQUENCE_PROFILES = '_PROFILE_SETTING_IDS = (\n\t"voice",\n\t"variant",\n\t"rate",\n\t"pitch",\n\t"inflection",\n\t"volume",\n\t"hsz",\n\t"rgh",\n\t"bth",\n\t"backquoteVoiceTags",\n\t"ABRDICT",\n\t"phrasePrediction",\n\t"pauseMode",\n\t"audioQuality",\n)\n\n\n_BOOLEAN_PROFILE_SETTING_IDS = frozenset(("backquoteVoiceTags", "ABRDICT", "phrasePrediction"))\n\n\n_INTEGER_PROFILE_SETTING_IDS = frozenset(("rate", "pitch", "inflection", "volume", "hsz", "rgh", "bth"))\n\n\n_profile_settings_by_stack = {}\n\n\n_pending_profile_setting_changes = {}\n\n\n_current_profile_stack = None\n\n\n_profile_switch_handler_registered = False\n\n\n_profile_snapshots_preloaded = False\n\n\n_MISSING_PROFILE_SETTING = object()\n\n\ndef _active_profile_stack():\n\tprofiles = getattr(config.conf, "profiles", ())\n\treturn tuple(getattr(profile, "name", None) or "normal configuration" for profile in profiles)\n\n\ndef _eloquence_settings_from(conf):\n\ttry:\n\t\tsettings = conf["speech"]["eloquence"]\n\texcept (KeyError, TypeError):\n\t\treturn {}\n\treturn {setting_id: settings[setting_id] for setting_id in _PROFILE_SETTING_IDS if setting_id in settings}\n\n\ndef _coerce_boolean_setting(value):\n\tif isinstance(value, str):\n\t\treturn value.strip().casefold() in {"1", "true", "yes", "on"}\n\treturn bool(value)\n\n\ndef _coerce_raw_profile_setting(setting_id, value):\n\tif setting_id in _BOOLEAN_PROFILE_SETTING_IDS:\n\t\treturn _coerce_boolean_setting(value)\n\tif setting_id in _INTEGER_PROFILE_SETTING_IDS:\n\t\treturn int(value)\n\treturn str(value)\n\n\ndef _eloquence_settings_from_profile_layers(profiles):\n\t"""Merge explicit Eloquence values directly from NVDA\'s raw profile layers."""\n\tsettings = {}\n\tfor profile in profiles:\n\t\tif not profile:\n\t\t\tcontinue\n\t\ttry:\n\t\t\tprofile_settings = profile["speech"]["eloquence"]\n\t\texcept (KeyError, TypeError):\n\t\t\tcontinue\n\t\tfor setting_id in _PROFILE_SETTING_IDS:\n\t\t\tif setting_id in profile_settings:\n\t\t\t\ttry:\n\t\t\t\t\tsettings[setting_id] = _coerce_raw_profile_setting(\n\t\t\t\t\t\tsetting_id,\n\t\t\t\t\t\tprofile_settings[setting_id],\n\t\t\t\t\t)\n\t\t\t\texcept (TypeError, ValueError):\n\t\t\t\t\tlog.warning(\n\t\t\t\t\t\t"Ignoring invalid raw Eloquence setting %s=%r in profile %r",\n\t\t\t\t\t\tsetting_id,\n\t\t\t\t\t\tprofile_settings[setting_id],\n\t\t\t\t\t\tgetattr(profile, "name", None),\n\t\t\t\t\t)\n\treturn settings\n\n\ndef _capture_unseen_active_profile(profile_stack):\n\t"""Capture an incoming profile before synth loading can contaminate its merged view."""\n\tif profile_stack in _profile_settings_by_stack:\n\t\treturn\n\tsettings = _eloquence_settings_from_profile_layers(getattr(config.conf, "profiles", ()))\n\tif not settings:\n\t\tsettings = _eloquence_settings_from(config.conf)\n\tif settings:\n\t\t_profile_settings_by_stack[profile_stack] = settings\n\t\tlog.debug(\n\t\t\t"Eloquence captured raw incoming profile snapshot: profiles=%s, rate=%s",\n\t\t\tprofile_stack,\n\t\t\tsettings.get("rate"),\n\t\t)\n\n\ndef _preload_named_profile_snapshots():\n\t"""Read named profiles before a settings dialog/audio switch can mutate them."""\n\tglobal _profile_snapshots_preloaded\n\tif _profile_snapshots_preloaded:\n\t\treturn\n\tlist_profiles = getattr(config.conf, "listProfiles", None)\n\tget_profile = getattr(config.conf, "_getProfile", None)\n\tprofiles = getattr(config.conf, "profiles", ())\n\tif not callable(list_profiles) or not callable(get_profile) or not profiles:\n\t\treturn\n\tbase_profile = profiles[0]\n\tfor profile_name in list_profiles():\n\t\tprofile_stack = ("normal configuration", profile_name)\n\t\tif profile_stack in _profile_settings_by_stack:\n\t\t\tcontinue\n\t\ttry:\n\t\t\tprofile = get_profile(profile_name)\n\t\t\tsettings = _eloquence_settings_from_profile_layers((base_profile, profile))\n\t\texcept Exception:\n\t\t\tlog.exception("Could not preload Eloquence snapshot for profile %s", profile_name)\n\t\t\tcontinue\n\t\tif not settings:\n\t\t\tcontinue\n\t\t_profile_settings_by_stack[profile_stack] = settings\n\t\tlog.debug(\n\t\t\t"Eloquence preloaded named profile snapshot: profiles=%s, rate=%s",\n\t\t\tprofile_stack,\n\t\t\tsettings.get("rate"),\n\t\t)\n\t_profile_snapshots_preloaded = True\n\n\ndef _remember_current_profile_setting(driver, setting_id, value):\n\tif getattr(driver, "_loading_profile_settings", False) or _current_profile_stack is None:\n\t\treturn\n\tprofile_stack = _current_profile_stack\n\tsettings = _profile_settings_by_stack.setdefault(profile_stack, {})\n\tpending_key = (profile_stack, setting_id)\n\t_pending_profile_setting_changes.setdefault(\n\t\tpending_key,\n\t\tsettings.get(setting_id, _MISSING_PROFILE_SETTING),\n\t)\n\tsettings[setting_id] = value\n\n\tdef confirm_if_config_was_updated():\n\t\t# Settings-ring changes write config immediately after calling the driver\n\t\t# setter.  Dialog controls do not write until Apply/OK.  Checking on the\n\t\t# next wx turn distinguishes a committed ring change from a pending dialog\n\t\t# edit while retaining NVDA\'s live-preview behavior.\n\t\tif _active_profile_stack() != profile_stack:\n\t\t\treturn\n\t\ttry:\n\t\t\tconfigured = config.conf["speech"]["eloquence"][setting_id]\n\t\texcept (KeyError, TypeError):\n\t\t\treturn\n\t\tif str(configured) == str(value):\n\t\t\t_pending_profile_setting_changes.pop(pending_key, None)\n\n\twx.CallAfter(confirm_if_config_was_updated)\n\n\ndef _discard_pending_profile_settings(profile_stack):\n\tsettings = _profile_settings_by_stack.get(profile_stack)\n\tif settings is None:\n\t\treturn\n\tfor pending_key, previous in list(_pending_profile_setting_changes.items()):\n\t\tstack, setting_id = pending_key\n\t\tif stack != profile_stack:\n\t\t\tcontinue\n\t\tif previous is _MISSING_PROFILE_SETTING:\n\t\t\tsettings.pop(setting_id, None)\n\t\telse:\n\t\t\tsettings[setting_id] = previous\n\t\tdel _pending_profile_setting_changes[pending_key]\n\n\ndef _commit_current_profile_settings(driver):\n\tif _current_profile_stack is None:\n\t\treturn\n\tsettings = {}\n\tfor setting_id in _PROFILE_SETTING_IDS:\n\t\ttry:\n\t\t\tsettings[setting_id] = getattr(driver, setting_id)\n\t\texcept Exception:\n\t\t\tlog.exception("Could not snapshot committed Eloquence setting %s", setting_id)\n\t_profile_settings_by_stack[_current_profile_stack] = settings\n\tfor pending_key in list(_pending_profile_setting_changes):\n\t\tif pending_key[0] == _current_profile_stack:\n\t\t\tdel _pending_profile_setting_changes[pending_key]\n\n\ndef _sync_profile_snapshot_to_config(profile_stack, settings):\n\t"""Keep NVDA\'s active profile cache aligned with the restored engine state."""\n\tif _active_profile_stack() != profile_stack:\n\t\tlog.warning(\n\t\t\t"Not persisting Eloquence snapshot for inactive profile stack %s",\n\t\t\tprofile_stack,\n\t\t)\n\t\treturn\n\ttry:\n\t\tconfigured_settings = config.conf["speech"]["eloquence"]\n\texcept (KeyError, TypeError):\n\t\tlog.exception("Could not access the active Eloquence configuration section")\n\t\treturn\n\tfor setting_id, value in settings.items():\n\t\ttry:\n\t\t\tconfigured_settings[setting_id] = value\n\t\texcept Exception:\n\t\t\tlog.exception(\n\t\t\t\t"Could not persist restored Eloquence setting %s for profile stack %s",\n\t\t\t\tsetting_id,\n\t\t\t\tprofile_stack,\n\t\t\t)\n\n\ndef _apply_profile_snapshot(driver, profile_stack, settings):\n\twas_loading = getattr(driver, "_loading_profile_settings", False)\n\tcorrected_settings = []\n\tdriver._loading_profile_settings = True\n\ttry:\n\t\tfor setting_id in _PROFILE_SETTING_IDS:\n\t\t\tif setting_id not in settings:\n\t\t\t\tcontinue\n\t\t\ttry:\n\t\t\t\tcurrent_value = getattr(driver, setting_id)\n\t\t\texcept Exception:\n\t\t\t\tcorrected_settings.append(setting_id)\n\t\t\telse:\n\t\t\t\tif str(current_value) != str(settings[setting_id]):\n\t\t\t\t\tcorrected_settings.append(setting_id)\n\t\t\ttry:\n\t\t\t\tsetattr(driver, setting_id, settings[setting_id])\n\t\t\texcept Exception:\n\t\t\t\tlog.exception(\n\t\t\t\t\t"Could not restore Eloquence setting %s for profile stack %s",\n\t\t\t\t\tsetting_id,\n\t\t\t\t\tprofile_stack,\n\t\t\t\t)\n\tfinally:\n\t\tdriver._loading_profile_settings = was_loading\n\t# The engine and NVDA\'s aggregated configuration must agree.  Otherwise an\n\t# audio-device-driven synth recreation can look correct for the rest of the\n\t# session while NVDA later writes the crossed values to disk on shutdown.\n\t_sync_profile_snapshot_to_config(profile_stack, settings)\n\tlog_profile_restore = log.info if corrected_settings else log.debug\n\tlog_profile_restore(\n\t\t"Eloquence corrected isolated profile settings: profiles=%s, settings=%s, "\n\t\t"rate=%s, raw ECI rate=%s",\n\t\tprofile_stack,\n\t\tcorrected_settings,\n\t\tgetattr(driver, "rate", None),\n\t\tdriver.getVParam(_eloquence.rate),\n\t)\n\n\ndef _handle_profile_switch(prevConf=None, **_kwargs):\n\tglobal _current_profile_stack\n\tincoming_stack = _active_profile_stack()\n\t_current_profile_stack = incoming_stack\n\tsnapshot = _profile_settings_by_stack.get(incoming_stack)\n\tif not snapshot:\n\t\treturn\n\tdriver = synthDriverHandler.getSynth()\n\tif driver is None or getattr(driver, "name", None) != "eloquence":\n\t\treturn\n\t_apply_profile_snapshot(driver, incoming_stack, snapshot)\n\n\ndef _ensure_profile_isolation_handler():\n\tglobal _current_profile_stack, _profile_switch_handler_registered\n\tif _current_profile_stack is None:\n\t\t_current_profile_stack = _active_profile_stack()\n\t\t_profile_settings_by_stack[_current_profile_stack] = _eloquence_settings_from(config.conf)\n\tif not _profile_switch_handler_registered:\n\t\t# This handler deliberately lives for the lifetime of the loaded module.\n\t\t# Unregistering it from SynthDriver.terminate would mutate NVDA\'s Action\n\t\t# while that Action is notifying listeners during an audio-device switch.\n\t\tconfig.post_configProfileSwitch.register(_handle_profile_switch)\n\t\t_profile_switch_handler_registered = True\n'

ELOQUENCE_DRIVER_METHODS = '\tdef loadSettings(self, onlyChanged=False):\n\t\t"""Load NVDA\'s synth settings and the add-on\'s profile-scoped dictionary."""\n\t\tactive_stack = _active_profile_stack()\n\t\t# On an audio-device profile change, NVDA can recreate the synth using a\n\t\t# merged configuration still carrying the outgoing profile\'s values.  The\n\t\t# raw ConfigObj layers already identify the incoming profile correctly, so\n\t\t# capture them before calling NVDA\'s loader for the first time this session.\n\t\t_capture_unseen_active_profile(active_stack)\n\t\t# Named profiles must be copied even earlier than their first activation.\n\t\t# NVDA can mutate the incoming profile layer before constructing this new\n\t\t# driver, so preload clean copies while the initial profile is still stable.\n\t\t_preload_named_profile_snapshots()\n\t\tif _current_profile_stack is not None:\n\t\t\t# A same-profile full load is NVDA\'s settings Cancel/reload path.  A\n\t\t\t# different active stack means a profile switch is in progress.  In both\n\t\t\t# cases, pending dialog previews were not committed and must not become a\n\t\t\t# durable profile snapshot.\n\t\t\t_discard_pending_profile_settings(_current_profile_stack)\n\t\tself._loading_profile_settings = True\n\t\ttry:\n\t\t\t# Activate the dictionary before loading voice parameters.  ECI dictionary\n\t\t\t# activation can alter the current voice state, so rate, pitch, volume and\n\t\t\t# the other NVDA profile settings must be the final writes to the engine.\n\t\t\ttry:\n\t\t\t\tdata_directory = os.path.dirname(_eloquence.eciPath)\n\t\t\t\tprofile = _eloquence_dictionaries.resolve_profile(\n\t\t\t\t\tconfig.conf.get("eloquence", {}),\n\t\t\t\t\tdata_directory,\n\t\t\t\t\tmigrate=not globalVars.appArgs.secure,\n\t\t\t\t)\n\t\t\t\tdirectory = _eloquence_dictionaries.active_directory(data_directory, profile)\n\t\t\t\t_eloquence.set_dictionary_directory(directory)\n\t\t\texcept Exception:\n\t\t\t\tlog.exception("Could not activate the Eloquence dictionary for the new configuration profile")\n\t\t\t# NVDA calls loadSettings for an in-place profile change and initSettings\n\t\t\t# calls it for a newly constructed driver.  Keeping both operations here\n\t\t\t# avoids a second post_configProfileSwitch handler while ensuring the\n\t\t\t# active profile\'s synth values win over all engine initialization.\n\t\t\tsuper().loadSettings(onlyChanged=onlyChanged)\n\t\tfinally:\n\t\t\tself._loading_profile_settings = False\n\t\t_ensure_profile_isolation_handler()\n\t\tif active_stack == _current_profile_stack:\n\t\t\tsnapshot = _profile_settings_by_stack.get(active_stack)\n\t\t\tif snapshot:\n\t\t\t\t_apply_profile_snapshot(self, active_stack, snapshot)\n\t\ttry:\n\t\t\tconfigured_rate = config.conf["speech"][self.name]["rate"]\n\t\texcept Exception:\n\t\t\tconfigured_rate = None\n\t\tactive_profiles = [\n\t\t\tgetattr(profile, "name", None) or "normal configuration"\n\t\t\tfor profile in getattr(config.conf, "profiles", ())\n\t\t]\n\t\tlog.debug(\n\t\t\t"Eloquence profile settings loaded: profiles=%s, configured rate=%s, "\n\t\t\t"applied rate=%s, raw ECI rate=%s, onlyChanged=%s",\n\t\t\tactive_profiles,\n\t\t\tconfigured_rate,\n\t\t\tself.rate,\n\t\t\tself.getVParam(_eloquence.rate),\n\t\t\tonlyChanged,\n\t\t)\n\n\tdef saveSettings(self):\n\t\t"""Save through NVDA, then commit the active Eloquence profile snapshot."""\n\t\twas_loading = getattr(self, "_loading_profile_settings", False)\n\t\tsuper().saveSettings()\n\t\tself._loading_profile_settings = False\n\t\t_ensure_profile_isolation_handler()\n\t\tif was_loading or synthDriverHandler.getSynth() is self:\n\t\t\t_commit_current_profile_settings(self)\n\n\tdef _get_pitch(self):\n\t\treturn self.getVParam(_eloquence.pitch)\n\n\tdef _set_pitch(self, vl):\n\t\tself.setVParam(_eloquence.pitch, vl)\n\t\t_remember_current_profile_setting(self, "pitch", int(vl))\n\n\tdef _get_volume(self):\n\t\treturn self.getVParam(_eloquence.vlm)\n\n\tdef _set_volume(self, vl):\n\t\tself.setVParam(_eloquence.vlm, int(vl))\n\t\t_remember_current_profile_setting(self, "volume", int(vl))\n\n\tdef getVParam(self, pr):\n\t\treturn _eloquence.getVParam(pr)\n\n\tdef setVParam(self, pr, vl):\n\t\t_eloquence.setVParam(pr, vl)\n'
